#include <iostream>

int main() {
    constexpr int n = 6;
    double datos[n] = {2.0, 4.0, 4.0, 4.0, 5.0, 9.0};
    double suma = 0.0;

    for (int i = 0; i < n; ++i) {
        suma += datos[i];
    }
    const double media = suma / n;

    double maxDesv = 0.0;
    for (int i = 0; i < n; ++i) {
        double desv = datos[i] - media;
        if (desv < 0.0) {
            desv = -desv;
        }
        if (desv > maxDesv) {
            maxDesv = desv;
        }
    }

    std::cout << "media = " << media << '\n';
    for (int i = 0; i < n; ++i) {
        std::cout << (datos[i] - media) / maxDesv << ' ';
    }
    std::cout << '\n';
    return 0;
}

