#include <iostream>

int main() {
    int numero = 0;
    std::cout << "Numero: ";
    std::cin >> numero;

    for (int i = 1; i <= 10; ++i) {
        std::cout << numero << " x " << i << " = " << numero * i << '\n';
    }
    return 0;
}

#include <iostream>

int main() {
    long long n = 0;
    std::cout << "Numero: ";
    std::cin >> n;

    if (n <= 0) {
        std::cerr << "Debe ser positivo\n";
        return 1;
    }

    int pasos = 0;
    while (n != 1) {
        if (n % 2 == 0) {
            n /= 2;
        } else {
            n = 3 * n + 1;
        }
        ++pasos;
    }

    std::cout << "Pasos: " << pasos << '\n';
    return 0;
}

